#!/usr/bin/env node
// Deployment gate only: NEVER issues a session or enables a route.
import fs from "node:fs";
import path from "node:path";
const [,, manifestPath] = process.argv;
function fail(code) { console.error("NATIVE_AUTH_NOT_READY:" + code); process.exitCode = 1; }
if (!manifestPath) fail("missing_manifest");
else {
  try {
    const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
    // Manifest must be generated by an operator from trusted server configuration.
    // Do not accept request headers, slot name, IP or browser input as a principal.
    if (manifest.schema !== 1 || manifest.identitySource !== "authenticated-reverse-proxy"
      || manifest.principalFrom !== "verified-upstream-auth"
      || manifest.sessionIssuer !== "server-only"
      || manifest.csrfPolicy !== "origin-and-session-bound"
      || manifest.workspacePolicy !== "principal-and-slot-isolated"
      || manifest.backendTokenPolicy !== "server-only-per-workspace"
      || manifest.crossSlotHttpTest !== "pass"
      || manifest.symlinkHttpTest !== "pass"
      || manifest.nativeRoundtripHttpTest !== "pass") fail("missing_security_proof");
    else console.log("NATIVE_AUTH_CONTRACT_READY (declaration only; routes remain disabled)");
  } catch { fail("invalid_manifest"); }
}